215	// DownloaderStoreConfig is the config that can restore the downloader.
216	type DownloaderStoreConfig struct {
217		FirstLoad bool `json:"-"` // FirstLoad is the flag that the config is first time init and not from store
218	
219		DownloadDir                string                 `json:"downloadDir"`    // DownloadDir is the default directory to save the downloaded files
220		MaxRunning                 int                    `json:"maxRunning"`     // MaxRunning is the max running download count
221		ProtocolConfig             map[string]any         `json:"protocolConfig"` // ProtocolConfig is special config for each protocol
222		GithubMirror               *GithubMirrorConfig    `json:"githubMirror"`
223		Extra                      map[string]any         `json:"extra"`
224		Proxy                      *DownloaderProxyConfig `json:"proxy"`
225		Webhook                    *WebhookConfig         `json:"webhook"`                    // Webhook is the webhook configuration
226		Script                     *ScriptConfig          `json:"script"`                     // Script is the script execution configuration
227		AutoTorrent                *AutoTorrentConfig     `json:"autoTorrent"`                // AutoTorrent is the auto torrent task creation configuration
228		Archive                    *ArchiveConfig         `json:"archive"`                    // Archive is the archive extraction configuration
229		Categories                 []*DownloadCategory    `json:"categories"`                 // Categories is the download directory category configuration
230		AutoCategorize             *bool                  `json:"autoCategorize,omitempty"`   // AutoCategorize routes downloads to category directories by file extension; unset defaults to disabled
231		API                        *APIServerConfig       `json:"api"`                        // API is the optional REST server configuration
232		AutoStartTasks             bool                   `json:"autoStartTasks"`             // AutoStartTasks continues all unfinished tasks when the backend starts
233		AutoDeleteMissingFileTasks bool                   `json:"autoDeleteMissingFileTasks"` // AutoDeleteMissingFileTasks enables automatic deletion of tasks with missing files
234	}
235	
236	func (cfg *DownloaderStoreConfig) Init() *DownloaderStoreConfig {
237		if cfg.MaxRunning == 0 {
238			cfg.MaxRunning = 5
239		}
240		if cfg.ProtocolConfig == nil {
241			cfg.ProtocolConfig = make(map[string]any)
242		}
243		if cfg.GithubMirror == nil {
244			cfg.GithubMirror = DefaultGithubMirrorConfig()
245		}
246		if cfg.Proxy == nil {
247			cfg.Proxy = &DownloaderProxyConfig{}
248		}
249		if cfg.Webhook == nil {
250			cfg.Webhook = &WebhookConfig{}
251		}
252		if cfg.Script == nil {
253			cfg.Script = &ScriptConfig{}
254		}
255		if cfg.AutoTorrent == nil {
256			cfg.AutoTorrent = &AutoTorrentConfig{
257				Enable:              false,
258				DeleteAfterDownload: false,
259			}
260		}
261		if cfg.Archive == nil {
262			cfg.Archive = &ArchiveConfig{
263				AutoExtract:        false,
264				DeleteAfterExtract: false,
265			}
266		}
267		// Seed the built-in categories for deployments that never run the flutter
268		// startup flow, e.g. headless api servers.
269		if len(cfg.Categories) == 0 && cfg.DownloadDir != "" {
270			cfg.Categories = []*DownloadCategory{
271				builtinSeedCategory("categoryMusic", "Music", cfg.DownloadDir),
272				builtinSeedCategory("categoryVideo", "Video", cfg.DownloadDir),
273				builtinSeedCategory("categoryDocument", "Document", cfg.DownloadDir),
274				builtinSeedCategory("categoryProgram", "Program", cfg.DownloadDir),
275			}
276		}
277		return cfg
278	}
279	
280	// builtinCategoryExtensions mirrors the flutter side
281	// kDefaultCategoryExtensions, keep both maps in sync.
282	var builtinCategoryExtensions = map[string][]string{
283		"categoryProgram":  {"exe", "msi", "msix", "apk", "dmg", "deb", "rpm", "pkg", "appimage"},
284		"categoryVideo":    {"mp4", "mkv", "avi", "mov", "wmv", "flv", "webm", "m4v", "mpg", "mpeg", "3gp"},
285		"categoryMusic":    {"mp3", "flac", "wav", "aac", "ogg", "m4a", "wma", "ape"},
286		"categoryDocument": {"pdf", "doc", "docx", "xls", "xlsx", "ppt", "pptx", "txt", "md", "csv", "epub", "rtf"},
287	}
288	
289	func builtinSeedCategory(nameKey, name, downloadDir string) *DownloadCategory {
290		return &DownloadCategory{
291			Name:       "",
292			Path:       filepath.Join(downloadDir, name),
293			NameKey:    nameKey,
294			IsBuiltIn:  true,
295			Extensions: append([]string(nil), builtinCategoryExtensions[nameKey]...),
296		}
297	}
298	
299	// MigrateLegacyExtraCategories moves the extra.downloadCategories list written
300	// by v2.0.0-beta builds into the top level categories field and clears the
301	// legacy key. The legacy list predates extension based routing, so built-in
302	// entries regain their default extension lists from their name key, while user
303	// created folders keep their empty list until edited in settings. It reports
304	// whether the config changed so the caller can persist the cleared key.
305	func (cfg *DownloaderStoreConfig) MigrateLegacyExtraCategories() bool {
306		if len(cfg.Categories) > 0 || cfg.Extra == nil {
307			return false
308		}
309		raw, ok := cfg.Extra["downloadCategories"]
310		if !ok {
311			return false
312		}
313		data, err := json.Marshal(raw)
314		if err != nil {
315			return false
316		}
317		var legacy []*DownloadCategory
318		if err := json.Unmarshal(data, &legacy); err != nil {
319			return false
320		}
321		categories := make([]*DownloadCategory, 0, len(legacy))
322		for _, category := range legacy {
323			if category == nil {
324				continue
325			}
326			if extensions, exist := builtinCategoryExtensions[category.NameKey]; exist && len(category.Extensions) == 0 {
327				category.Extensions = append([]string(nil), extensions...)
328			}
329			categories = append(categories, category)
330		}
331		if len(categories) == 0 {
332			return false
333		}
334		cfg.Categories = categories
335		delete(cfg.Extra, "downloadCategories")
336		return true
337	}
338	
339	// AutoCategorizeEnabled reports whether downloads are routed to category
340	// directories by file extension. The switch is optional: an unset value keeps
341	// the feature off, so an older config that never saved the field stays off.
342	func (cfg *DownloaderStoreConfig) AutoCategorizeEnabled() bool {
343		return cfg.AutoCategorize != nil && *cfg.AutoCategorize
344	}
345	
346	func (cfg *DownloaderStoreConfig) Merge(beforeCfg *DownloaderStoreConfig) *DownloaderStoreConfig {
347		if beforeCfg == nil {
348			return cfg
349		}
350		if cfg.DownloadDir == "" {
351			cfg.DownloadDir = beforeCfg.DownloadDir
352		}
353		if cfg.MaxRunning == 0 {
354			cfg.MaxRunning = beforeCfg.MaxRunning
355		}
356		if cfg.ProtocolConfig == nil {
357			cfg.ProtocolConfig = beforeCfg.ProtocolConfig
358		}
359		if cfg.Extra == nil {
360			cfg.Extra = beforeCfg.Extra
361		}
362		if cfg.GithubMirror == nil {
363			cfg.GithubMirror = beforeCfg.GithubMirror
364		}
365		if cfg.Proxy == nil {
366			cfg.Proxy = beforeCfg.Proxy
367		}
368		if cfg.Webhook == nil {
369			cfg.Webhook = beforeCfg.Webhook
370		}
371		if cfg.Script == nil {
372			cfg.Script = beforeCfg.Script
373		}
374		if cfg.AutoTorrent == nil {
375			cfg.AutoTorrent = beforeCfg.AutoTorrent
376		}
377		if cfg.Archive == nil {
378			cfg.Archive = beforeCfg.Archive
379		}
380		if cfg.Categories == nil {
381			cfg.Categories = beforeCfg.Categories
382		}
383		if cfg.AutoCategorize == nil {
384			cfg.AutoCategorize = beforeCfg.AutoCategorize
385		}
386		if cfg.API == nil {
387			cfg.API = beforeCfg.API
388		}
389		return cfg
390	}
