215	// DownloaderStoreConfig is the config that can restore the downloader.
216	type DownloaderStoreConfig struct {
217		FirstLoad bool `json:"-"` // FirstLoad is the flag that the config is first time init and not from store
218	
219		DownloadDir                string                 `json:"downloadDir"`    // DownloadDir is the default directory to save the downloaded files
220		MaxRunning                 int                    `json:"maxRunning"`     // MaxRunning is the max running download count
221		ProtocolConfig             map[string]any         `json:"protocolConfig"` // ProtocolConfig is special config for each protocol
222		GithubMirror               *GithubMirrorConfig    `json:"githubMirror"`
223		Extra                      map[string]any         `json:"extra"`
224		Proxy                      *DownloaderProxyConfig `json:"proxy"`
225		Webhook                    *WebhookConfig         `json:"webhook"`                    // Webhook is the webhook configuration
226		Script                     *ScriptConfig          `json:"script"`                     // Script is the script execution configuration
227		AutoTorrent                *AutoTorrentConfig     `json:"autoTorrent"`                // AutoTorrent is the auto torrent task creation configuration
228		Archive                    *ArchiveConfig         `json:"archive"`                    // Archive is the archive extraction configuration
229		Categories                 []*DownloadCategory    `json:"categories"`                 // Categories is the download directory category configuration
230		AutoCategorize             *bool                  `json:"autoCategorize,omitempty"`   // AutoCategorize routes downloads to category directories by file extension; unset defaults to disabled
231		API                        *APIServerConfig       `json:"api"`                        // API is the optional REST server configuration
232		AutoStartTasks             bool                   `json:"autoStartTasks"`             // AutoStartTasks continues all unfinished tasks when the backend starts
233		AutoDeleteMissingFileTasks bool                   `json:"autoDeleteMissingFileTasks"` // AutoDeleteMissingFileTasks enables automatic deletion of tasks with missing files
234	}
