664	func (d *Downloader) CreateDirectBatchWithResult(req *base.CreateTaskBatch) (*CreateTaskBatchResult, error) {
665		if req == nil || len(req.Reqs) == 0 {
666			return nil, errors.New("batch requires at least one task")
667		}
668		defaultPath, err := d.prepareDefaultPath(req.Opts)
669		if err != nil {
670			return nil, err
671		}
672		result := &CreateTaskBatchResult{TaskIDs: make([]string, 0)}
673		var group *TaskGroup
674		if req.Group {
675			parentPath := ""
676			if req.Opts != nil {
677				parentPath = req.Opts.Path
678			}
679			group, err = d.createTaskGroup(req.GroupName, parentPath)
680			if err != nil {
681				return nil, err
682			}
683			result.ParentID = group.ID
684			defer func() {
685				d.lock.Lock()
686				delete(d.creatingGroups, group.ID)
687				d.lock.Unlock()
688				d.cleanupEmptyGroups([]string{group.ID})
689			}()
690		}
691		var failures []error
692		for _, item := range req.Reqs {
693			var taskID string
694			var opts *base.Options
695			if item != nil {
696				opts = item.Opts
697			}
698			if opts == nil {
699				opts = req.Opts
700			}
701			if opts == nil {
702				opts = &base.Options{}
703			} else {
704				opts = opts.Clone()
705			}
706			var itemErr error
707			groupID := ""
708			if group != nil {
709				groupID = group.ID
710				parentPath := filepath.Dir(group.Path)
711				relative := "."
712				if item != nil && item.Opts != nil && opts.Path != "" {
713					requestedPath := util.ReplacePathPlaceholders(opts.Path)
714					if !filepath.IsAbs(requestedPath) {
715						requestedPath = filepath.Join(parentPath, requestedPath)
716					}
717					requested, pathErr := filepath.Abs(requestedPath)
718					if pathErr != nil {
719						itemErr = pathErr
720					} else {
721						relative, itemErr = filepath.Rel(parentPath, requested)
722						if itemErr == nil && !filepath.IsLocal(relative) {
723							itemErr = errors.New("task path is outside the group directory")
724						}
725					}
726				}
727				opts.Path = filepath.Join(group.Path, relative)
728				opts.SkipAutoCategorize = true
729			}
730			if itemErr == nil {
731				switch {
732				case item == nil:
733					itemErr = errors.New("task request or rid is required")
734				case item.Rid != "":
735					taskID, itemErr = d.createResolved(item.Rid, opts, groupID)
736				case item.Req != nil:
737					taskID, itemErr = d.createDirect(item.Req, opts, groupID)
738				default:
739					itemErr = errors.New("task request or rid is required")
740				}
741			}
742			if taskID != "" {
743				result.TaskIDs = append(result.TaskIDs, taskID)
744			} else if itemErr != nil {
745				failures = append(failures, itemErr)
746			}
747		}
748		if len(result.TaskIDs) == 0 {
749			return nil, fmt.Errorf("all batch tasks failed: %w", errors.Join(failures...))
750		}
751		d.persistDefaultPathBestEffort(defaultPath)
752		return result, nil
753	}
