755	const maxTaskGroupDirSuffix = 1000
756	
757	func (d *Downloader) createTaskGroup(name, parentPath string) (*TaskGroup, error) {
758		parentOpts, err := d.initOptions(&base.Options{Path: parentPath}, "")
759		if err != nil {
760			return nil, err
761		}
762		parentPath = util.ReplacePathPlaceholders(strings.TrimSpace(parentOpts.Path))
763		if parentPath == "" {
764			return nil, errors.New("download directory is empty")
765		}
766		parentPath, err = filepath.Abs(parentPath)
767		if err != nil {
768			return nil, err
769		}
770		name = strings.TrimSpace(name)
771		if strings.ContainsAny(name, "/\\\x00") || filepath.IsAbs(name) {
772			return nil, errors.New("invalid task group name")
773		}
774		if strings.ContainsAny(name, `:*?"<>|`) || strings.HasSuffix(name, ".") {
775			return nil, errors.New("invalid task group name")
776		}
777		name = util.SafeFilename(name)
778		if name == "" || name == "." || name == ".." {
779			return nil, errors.New("invalid task group name")
780		}
781		d.lock.Lock()
782		defer d.lock.Unlock()
783		requested := filepath.Join(parentPath, name)
784		var dir string
785		for suffix := 0; suffix <= maxTaskGroupDirSuffix; suffix++ {
786			candidate := requested
787			if suffix > 0 {
788				candidate = fmt.Sprintf("%s (%d)", requested, suffix)
789			}
790			if !d.isDownloadPathAllowed(candidate) {
791				return nil, errors.New("task group directory is outside the white list")
792			}
793			reserved := false
794			for _, existing := range d.groups {
795				if existing.Path == candidate {
796					reserved = true
797					break
798				}
799			}
800			if reserved {
801				continue
802			}
803			if err := os.MkdirAll(parentPath, 0755); err != nil {
804				return nil, err
805			}
806			if err := os.Mkdir(candidate, 0755); err != nil {
807				if errors.Is(err, os.ErrExist) {
808					continue
809				}
810				return nil, err
811			}
812			dir = candidate
813			break
814		}
815		if dir == "" {
816			return nil, errors.New("too many duplicate task group directories")
817		}
818		group := &TaskGroup{ID: NewTask().ID, Name: filepath.Base(dir), Path: dir, CreatedAt: time.Now()}
819		if err := d.storage.Put(bucketTaskGroup, group.ID, group); err != nil {
820			_ = os.Remove(dir)
821			return nil, err
822		}
823		d.groups[group.ID] = group
824		d.creatingGroups[group.ID] = struct{}{}
825		return group, nil
826	}
