95	// asciiLower lowercases the ascii letters of s and leaves the rest alone. The
96	// ui lowercases the same way, because the unicode case tables of the two
97	// languages disagree for some code points and would let the two sides pick a
98	// different category for the same file.
99	func asciiLower(s string) string {
100		hasUpper := false
101		for i := 0; i < len(s); i++ {
102			if c := s[i]; c >= 'A' && c <= 'Z' {
103				hasUpper = true
104				break
105			}
106		}
107		if !hasUpper {
108			return s
109		}
110		b := []byte(s)
111		for i, c := range b {
112			if c >= 'A' && c <= 'Z' {
113				b[i] = c + ('a' - 'A')
114			}
115		}
116		return string(b)
117	}
