119	// matchDownloadCategory returns the first category whose extension list
120	// contains the extension of the given file name, or nil when nothing matches.
121	// An empty extension list never matches.
122	func matchDownloadCategory(cfg *base.DownloaderStoreConfig, name string) *base.DownloadCategory {
123		ext := fileExtension(name)
124		if ext == "" {
125			return nil
126		}
127		for _, category := range cfg.Categories {
128			if category == nil || category.IsDeleted || dartTrimSpace(category.Path) == "" {
129				continue
130			}
131			for _, e := range normalizeCategoryExtensions(category.Extensions) {
132				if e == ext {
133					return category
134				}
135			}
136		}
137		return nil
138	}
139	
140	// normalizeCategoryExtensions mirrors the dart side: entries are split on
141	// commas and whitespace, trimmed, lowercased, stripped of leading dots and
142	// deduplicated while keeping the input order, so a stored value like
143	// "exe, msi" behaves the same in the backend as it does in the ui.
144	func normalizeCategoryExtensions(raw []string) []string {
145		var result []string
146		seen := make(map[string]struct{}, len(raw))
147		for _, item := range raw {
148			for _, part := range strings.FieldsFunc(item, func(r rune) bool {
149				return r == ',' || isECMAScriptSpace(r)
150			}) {
151				ext := asciiLower(strings.TrimLeft(dartTrimSpace(part), "."))
152				if ext == "" {
153					continue
154				}
155				if _, ok := seen[ext]; ok {
156					continue
157				}
158				seen[ext] = struct{}{}
159				result = append(result, ext)
160			}
161		}
162		return result
163	}
164	
165	// fileExtension returns the lower case extension of a file name without the
166	// leading dot, e.g. "setup.exe" -> "exe". Windows style separators are
167	// treated like the ui does, so a dot inside a directory segment never counts
168	// as an extension.
169	func fileExtension(name string) string {
170		name = strings.ReplaceAll(name, `\`, "/")
171		return strings.TrimPrefix(asciiLower(path.Ext(name)), ".")
172	}
173	
174	// dartTrimSpace trims the whitespace the dart String.trim() removes, which is
175	// the unicode white space set plus the byte order mark. The ui trims the
176	// category paths and the extension lists with it, so the backend uses the same
177	// set instead of the narrower unicode.IsSpace.
178	func dartTrimSpace(s string) string {
179		return strings.TrimFunc(s, func(r rune) bool {
180			return unicode.IsSpace(r) || r == 0xFEFF
181		})
182	}
183	
184	// isECMAScriptSpace reports whether r belongs to the whitespace class of the
185	// ECMAScript regular expressions. The ui splits its extension lists with that
186	// class, so the backend uses the same one instead of the wider unicode.IsSpace.
187	func isECMAScriptSpace(r rune) bool {
188		switch r {
189		case '\t', '\n', '\v', '\f', '\r', ' ', 0x00A0, 0x1680, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000, 0xFEFF:
190			return true
191		}
192		return r >= 0x2000 && r <= 0x200A
193	}
